using System;using System.Linq;using System.Windows.Forms;using BeamScheduleFormatter;
class RowHistoryUiTests {
 static int checks;static void Check(bool yes,string name){checks++;if(!yes)throw new Exception(name);}
 [STAThread]static void Main(){using(var form=new Form()){var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=true,AllowUserToDeleteRows=true,MultiSelect=true};grid.Columns.Add("ID","ID");grid.Columns.Add("Diameter","Rebar diameter mm");grid.Columns.Add("Computed","Computed kg");grid.Columns[2].ReadOnly=true;grid.Rows.Add("A",12,4.5);grid.Rows.Add("B",16,7.5);grid.Rows.Add("C",20,12.5);form.Controls.Add(grid);bool busy=false;int changed=0;GridEditHistory.Configure(grid,()=>busy,v=>busy=v,()=>changed++);var history=GridEditHistory.Attach(grid);form.Show();Application.DoEvents();grid.CurrentCell=grid.Rows[1].Cells[1];grid.BeginEdit(false);((TextBox)grid.EditingControl).Text="18";grid.EndEdit();Application.DoEvents();Check(history.CanUndo,"Committed cell edit recorded");history.Undo();Check(Convert.ToInt32(grid.Rows[1].Cells[1].Value)==16,"Undo restores edited input");history.Redo();Check(Convert.ToInt32(grid.Rows[1].Cells[1].Value)==18,"Redo restores edited input");history.Undo();int beforeDeleteChanged=changed;grid.ClearSelection();grid.Rows[0].Selected=true;grid.Rows[2].Selected=true;int confirmed=0;GridEditHistory.ConfirmDelete=(owner,count)=>{confirmed=count;return false;};history.DeleteSelected();Check(confirmed==2&&grid.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow)==3,"Cancel confirmation retains both selected rows");GridEditHistory.ConfirmDelete=(owner,count)=>true;history.DeleteSelected();Check(grid.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow)==1&&Convert.ToString(grid.Rows[0].Cells[0].Value)=="B","Delete two rows in one operation");Check(changed==beforeDeleteChanged+1,"Bulk delete recalculates once");history.Undo();Check(grid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>Convert.ToString(r.Cells[0].Value)).SequenceEqual(new[]{"A","B","C"}),"Undo restores row values and ordering");Check(Convert.ToInt32(grid.Rows[1].Cells[1].Value)==16&&grid.Rows[1].Cells[2].ReadOnly,"Numeric diameter and computed protection restored");history.Redo();Check(grid.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow)==1,"Redo bulk delete");history.Undo();busy=true;grid.Rows.Clear();busy=false;Check(!history.CanUndo&&!history.CanRedo,"Opening another project clears stale history");}Console.WriteLine("PASS: "+checks+" native row history/confirmation checks");}
}
